 void calculate(){
 if(destination==null||loc==null){toast("Aguardando localização");return;}
 if(!driving&&hasTrafficRegion(gp(loc))&&(fetchingTraffic||lastTrafficAttempt==0||SystemClock.elapsedRealtime()-lastTrafficAttempt>20000)){waitingTrafficRoute=true;int generation=++trafficRouteGeneration;summary.setText("Consultando trânsito e rotas…");if(!fetchingTraffic)refreshTraffic();main.postDelayed(()->{if(waitingTrafficRoute&&generation==trafficRouteGeneration){waitingTrafficRoute=false;calculateNow(false);}},4500);return;}
 waitingTrafficRoute=false;calculateNow(false);
 }
 void calculateNow(boolean trafficOnly){
 if(destination==null||loc==null)return;
 if(mode.equals("bus")){toast("Transporte público ainda sem itinerários integrados.");mode="car";renderRoute();return;}
 final int token=++request;final GeoPoint start=gp(loc);final ArrayList<Place> via=new ArrayList<>(stops);final Place dest=destination;final String profile=mode;
 final boolean tolls=avoidTolls,highways=avoidHighways,hills=avoidHills,risk=avoidRisk,wasDriving=driving;
 final ArrayList<Jam> currentJams=new ArrayList<>(jams);final ArrayList<Event> currentAlerts=new ArrayList<>(live);final Route prior=wasDriving&&!routes.isEmpty()?routes.get(selected):null;
 calculating=true;lastRouteAttempt=SystemClock.elapsedRealtime();if(!trafficOnly)summary.setText("Calculando rota…");
 routePool.execute(()->{try{
 ArrayList<Route> rr;boolean preferred=tolls||highways||(hills&&profile.equals("walk"))||profile.equals("moto")||risk&&currentAlerts.stream().anyMatch(e->e.kind.equals("interdicao")&&e.expires>System.currentTimeMillis());
 try{rr=preferred?valRoutes(start,via,dest,profile,tolls,highways,hills,risk,currentAlerts):osRoutes(start,via,dest,profile);}
 catch(Exception ex){if(profile.equals("moto")||tolls||highways||(hills&&profile.equals("walk")))throw ex;rr=preferred?osRoutes(start,via,dest,profile):valRoutes(start,via,dest,profile,false,false,false,risk,currentAlerts);}
 if(rr.isEmpty())throw new IOException("Nenhuma rota disponível");
 for(Route x:rr)x.extraDelay=estimateJamDelay(x,currentJams,0);
 rr.sort(Comparator.comparingDouble(x->x.seconds+x.extraDelay));final ArrayList<Route> found=rr;
 main.post(()->{if(token!=request)return;calculating=false;if(trafficOnly){if(!driving||loc==null||prior==null||routes.isEmpty()||routes.get(selected)!=prior)return;double[] oldPos=project(gp(loc),prior.points);Route candidate=found.get(0);double[] newPos=project(gp(loc),candidate.points);if(newPos[1]>55||oldPos[1]>55)return;double oldRemaining=prior.seconds*Math.max(0,1-oldPos[0]/Math.max(1,oldPos[2]))+estimateJamDelay(prior,jams,oldPos[0]);double newRemaining=candidate.seconds*Math.max(0,1-newPos[0]/Math.max(1,newPos[2]))+estimateJamDelay(candidate,jams,newPos[0]);if(oldRemaining-newRemaining<Math.max(120,oldRemaining*.12))return;say("Nova rota com menos trânsito.");}origin=start;routes=found;selected=0;stepIndex=0;offRouteSamples=0;lastEtaRefresh=0;cachedDelay=found.get(0).extraDelay;if(!trafficOnly)warned.clear();else warned.removeIf(k->k.startsWith("step"));drawRoutes();renderRoute();if(driving&&loc!=null){followCamera(loc);progress();}});
 }catch(Exception e){main.post(()->{if(token!=request)return;calculating=false;if(wasDriving&&!routes.isEmpty()){if(!trafficOnly)toast("Não foi possível recalcular. Mantendo a rota anterior.");progress();}else{routes.clear();drawRoutes();summary.setText("Não foi possível calcular");renderRoute();toast("Verifique a conexão ou altere as preferências da rota.");}});}});
 }
 ArrayList<Route> osRoutes(GeoPoint start,ArrayList<Place> via,Place dest,String profile)throws Exception{
 String coords=start.getLongitude()+","+start.getLatitude();for(Place p:via)coords+=";"+p.p.getLongitude()+","+p.p.getLatitude();coords+=";"+dest.p.getLongitude()+","+dest.p.getLatitude();
 JSONArray a=new JSONObject(get("https://routing.openstreetmap.de/routed-"+(profile.equals("walk")?"foot":"car")+"/route/v1/driving/"+coords+"?steps=true&overview=full&geometries=geojson&alternatives="+(via.isEmpty()?"3":"false"))).getJSONArray("routes");
 ArrayList<Route> rr=new ArrayList<>();for(int i=0;i<a.length();i++){Route q=osRoute(a.getJSONObject(i));q.provider="OSRM";rr.add(q);}return rr;}
 ArrayList<Route> valRoutes(GeoPoint start,ArrayList<Place> via,Place dest,String profile,boolean tolls,boolean highways,boolean hills,boolean risk,ArrayList<Event> alerts)throws Exception{
 String costing=profile.equals("walk")?"pedestrian":profile.equals("moto")?"motorcycle":"auto";
 JSONArray points=new JSONArray();points.put(valPoint(start));for(Place p:via)points.put(valPoint(p.p));points.put(valPoint(dest.p));
 JSONObject opt=new JSONObject();if(!profile.equals("walk")){if(tolls)opt.put("use_tolls",0.0);if(highways)opt.put("use_highways",0.1);}else if(hills)opt.put("use_hills",0.0);
 JSONObject body=new JSONObject().put("locations",points).put("costing",costing).put("costing_options",new JSONObject().put(costing,opt)).put("units","kilometers").put("language","pt-BR").put("alternates",via.isEmpty()?2:0);
 if(risk){JSONArray avoid=new JSONArray();for(Event e:alerts){if(avoid.length()>=25)break;if(e.kind.equals("interdicao")&&e.expires>System.currentTimeMillis()&&e.p.distanceToAsDouble(start)<30000)avoid.put(valPoint(e.p));}if(avoid.length()>0)body.put("exclude_locations",avoid);}
 JSONObject v=new JSONObject(get("https://valhalla1.openstreetmap.de/route?json="+enc(body.toString())));ArrayList<Route> rr=new ArrayList<>();rr.add(valRoute(v.getJSONObject("trip")));JSONArray aa=v.optJSONArray("alternates");if(aa!=null)for(int i=0;i<aa.length();i++)rr.add(valRoute(aa.getJSONObject(i).getJSONObject("trip")));for(Route q:rr)q.provider="Valhalla";return rr;
 }
 double estimateJamDelay(Route r,List<Jam> data,double from){
 if(r.points.size()<2)return 0;double delay=0;HashSet<String> used=new HashSet<>();long now=System.currentTimeMillis();
 for(Jam j:data){if(j.expires<now||j.level<2||j.points.size()<2||j.delay==0||j.delay<0&&j.level!=5)continue;String id=j.id.split(":")[0];if(used.contains(id))continue;double overlap=0,total=0;
 for(int i=1;i<j.points.size();i++){GeoPoint a=j.points.get(i-1),b=j.points.get(i);double len=a.distanceToAsDouble(b);if(len<1)continue;total+=len;GeoPoint mid=a.destinationPoint(len/2,a.bearingTo(b));double[] pos=project(mid,r.points);double heading=(a.bearingTo(b)+360)%360;if(pos[0]>=from-20&&pos[1]<35&&Math.abs((heading-pos[3]+540)%360-180)<65)overlap+=len;}
 if(total>0&&overlap/total>=.25){used.add(id);if(j.delay>0)delay+=Math.min(1800,j.delay)*Math.min(1,overlap/total);}}
 return Math.min(delay,Math.max(0,r.seconds*1.5));
 }
 JSONObject valPoint(GeoPoint p)throws Exception{return new JSONObject().put("lat",p.getLatitude()).put("lon",p.getLongitude());}
 Route osRoute(JSONObject j)throws Exception{Route r=new Route();r.meters=j.getDouble("distance");r.seconds=j.getDouble("duration");JSONArray a=j.getJSONObject("geometry").getJSONArray("coordinates");for(int i=0;i<a.length();i++)r.points.add(coord(a.getJSONArray(i)));JSONArray legs=j.getJSONArray("legs");for(int i=0;i<legs.length();i++){JSONArray s=legs.getJSONObject(i).getJSONArray("steps");for(int k=0;k<s.length();k++){JSONObject x=s.getJSONObject(k),m=x.getJSONObject("maneuver");String mod=m.optString("modifier");String dir=mod.contains("left")?"à esquerda":mod.contains("right")?"à direita":mod.equals("uturn")?"e faça o retorno":"em frente";String type=m.optString("type");String desc=type.equals("arrive")?"Você chegou ao destino":type.equals("depart")?"Inicie o trajeto":type.contains("roundabout")?(m.has("exit")?"Na rotatória, pegue a saída "+m.optInt("exit"):"Siga pela rotatória"):mod.equals("uturn")?"Faça o retorno":type.equals("continue")||mod.equals("straight")?"Continue em frente":mod.contains("slight")?"Mantenha-se "+dir:"Vire "+dir;r.steps.add(new Step(coord(m.getJSONArray("location")),desc+(x.optString("name").isEmpty()?"":" na "+x.optString("name")),x.optString("name"),type.equals("arrive")?"pin":type.contains("roundabout")?"round":mod.equals("uturn")?"uturn":mod.contains("left")?"left":mod.contains("right")?"right":"straight"));}}return r;}
 GeoPoint coord(JSONArray a)throws Exception{return new GeoPoint(a.getDouble(1),a.getDouble(0));}
 Route valRoute(JSONObject trip)throws Exception{Route r=new Route();r.meters=trip.getJSONObject("summary").getDouble("length")*1000;r.seconds=trip.getJSONObject("summary").getDouble("time");JSONArray legs=trip.getJSONArray("legs");for(int i=0;i<legs.length();i++){JSONObject l=legs.getJSONObject(i);ArrayList<GeoPoint> line=decode(l.getString("shape"));r.points.addAll(line);JSONArray a=l.getJSONArray("maneuvers");for(int k=0;k<a.length();k++){JSONObject m=a.getJSONObject(k);int index=m.optInt("begin_shape_index");if(index<line.size())r.steps.add(new Step(line.get(index),m.optString("instruction")));}}return r;}
 ArrayList<GeoPoint> decode(String s){ArrayList<GeoPoint> a=new ArrayList<>();int i=0,lat=0,lon=0;while(i<s.length()){int[] v=new int[2];for(int k=0;k<2;k++){int x=0,shift=0,b;do{b=s.charAt(i++)-63;x|=(b&31)<<shift;shift+=5;}while(b>=32);v[k]=(x&1)!=0?~(x>>1):x>>1;}lat+=v[0];lon+=v[1];a.add(new GeoPoint(lat/1e6,lon/1e6));}return a;}
