 void followCamera(Location l){
 float next=Float.NaN;
 if(!compassMode&&l.hasBearing()&&l.hasSpeed()&&l.getSpeed()>=2.8f&&(Build.VERSION.SDK_INT<26||!l.hasBearingAccuracy()||l.getBearingAccuracyDegrees()<40))next=l.getBearing();
 else if(Float.isFinite(phoneHeading)&&SystemClock.elapsedRealtime()-phoneHeadingAt<2500)next=phoneHeading;
 else if(!routes.isEmpty()){double[] p=project(gp(l),routes.get(selected).points);if(p[1]<60)next=(float)p[3];}
 if(Float.isFinite(next)){heading=headingSet?(heading+360+(float)((next-heading+540)%360-180)*.72f)%360:next;headingSet=true;}
 if(!followEnabled){if(vector!=null)vector.position();return;}
 if(vector!=null&&vector.active()){vector.camera(navigationPoint(),heading,tiltEnabled,true);return;}
 map.setMapOrientation(-heading);map.setRotationX(0);map.setScaleX(1);map.setScaleY(1);
 GeoPoint here=navigationPoint();double resolution=156543.03392*Math.cos(Math.toRadians(here.getLatitude()))/Math.pow(2,map.getZoomLevelDouble());double ahead=Math.max(40,Math.min(180,resolution*map.getHeight()*.20));map.getController().setCenter(here.destinationPoint(ahead,heading));if(car!=null)car.setRotation(-heading);
 }
 String streetFromInstruction(String t){int i=t.toLowerCase(Locale.ROOT).indexOf(" para ");if(i>=0)return t.substring(i+6).replaceAll("[.]$","");return t;}
 void startOrientation(){if(sensors==null)sensors=(android.hardware.SensorManager)getSystemService(SENSOR_SERVICE);if(sensors==null)return;android.hardware.Sensor sensor=sensors.getDefaultSensor(android.hardware.Sensor.TYPE_ROTATION_VECTOR);if(sensor==null)sensor=sensors.getDefaultSensor(android.hardware.Sensor.TYPE_GEOMAGNETIC_ROTATION_VECTOR);if(sensor==null)return;
 if(orientationListener==null)orientationListener=new android.hardware.SensorEventListener(){public void onAccuracyChanged(android.hardware.Sensor s,int a){} public void onSensorChanged(android.hardware.SensorEvent e){if(e.accuracy==android.hardware.SensorManager.SENSOR_STATUS_UNRELIABLE)return;float[] rotation=new float[9],adjusted=new float[9],angles=new float[3];android.hardware.SensorManager.getRotationMatrixFromVector(rotation,e.values);int screen=getWindowManager().getDefaultDisplay().getRotation(),axisX=android.hardware.SensorManager.AXIS_X,axisY=android.hardware.SensorManager.AXIS_Y;if(screen==Surface.ROTATION_90){axisX=android.hardware.SensorManager.AXIS_Y;axisY=android.hardware.SensorManager.AXIS_MINUS_X;}else if(screen==Surface.ROTATION_180){axisX=android.hardware.SensorManager.AXIS_MINUS_X;axisY=android.hardware.SensorManager.AXIS_MINUS_Y;}else if(screen==Surface.ROTATION_270){axisX=android.hardware.SensorManager.AXIS_MINUS_Y;axisY=android.hardware.SensorManager.AXIS_X;}android.hardware.SensorManager.remapCoordinateSystem(rotation,axisX,axisY,adjusted);android.hardware.SensorManager.getOrientation(adjusted,angles);float h=(float)Math.toDegrees(angles[0]);if(loc!=null){android.hardware.GeomagneticField field=new android.hardware.GeomagneticField((float)loc.getLatitude(),(float)loc.getLongitude(),(float)loc.getAltitude(),System.currentTimeMillis());h+=field.getDeclination();}phoneHeading=(h+360)%360;phoneHeadingAt=SystemClock.elapsedRealtime();if(driving&&followEnabled&&loc!=null&&(compassMode||!loc.hasSpeed()||loc.getSpeed()<2.8f)&&phoneHeadingAt-lastCompassCamera>180){lastCompassCamera=phoneHeadingAt;followCamera(loc);}}};sensors.registerListener(orientationListener,sensor,android.hardware.SensorManager.SENSOR_DELAY_UI);
 }
