 void configureVoice(){if(tts==null)return;tts.setPitch(1.0f);tts.setSpeechRate(.97f);tts.setAudioAttributes(new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_ASSISTANCE_NAVIGATION_GUIDANCE).setContentType(android.media.AudioAttributes.CONTENT_TYPE_SPEECH).build());Set<android.speech.tts.Voice> voices=tts.getVoices();if(voices==null)return;String preferred=getPreferences(0).getString("voice","");android.speech.tts.Voice best=null;for(android.speech.tts.Voice v:voices){if(!v.getLocale().getLanguage().equals("pt")||!v.getLocale().getCountry().equalsIgnoreCase("BR"))continue;if(v.getName().equals(preferred)){best=v;break;}if(v.getFeatures()!=null&&v.getFeatures().contains(TextToSpeech.Engine.KEY_FEATURE_NOT_INSTALLED))continue;if(!v.isNetworkConnectionRequired()&&(best==null||v.getQuality()>best.getQuality()||(v.getQuality()==best.getQuality()&&v.getLatency()<best.getLatency())))best=v;}if(best!=null)tts.setVoice(best);}
 void voiceDialog(){if(tts==null||!voiceReady){toast("Voz ainda indisponível");return;}ArrayList<android.speech.tts.Voice> voices=new ArrayList<>();Set<android.speech.tts.Voice> all=tts.getVoices();if(all!=null)for(android.speech.tts.Voice v:all)if(v.getLocale().getLanguage().equals("pt")&&v.getLocale().getCountry().equalsIgnoreCase("BR")&&(v.getFeatures()==null||!v.getFeatures().contains(TextToSpeech.Engine.KEY_FEATURE_NOT_INSTALLED)))voices.add(v);voices.sort((a,b)->Integer.compare(b.getQuality(),a.getQuality()));String[] labels=new String[voices.size()+1];labels[0]="Automática · melhor voz local";for(int i=0;i<voices.size();i++)labels[i+1]="Voz "+(i+1)+(voices.get(i).isNetworkConnectionRequired()?" · internet":" · local");new AlertDialog.Builder(this).setTitle("Voz de navegação").setItems(labels,(d,i)->{getPreferences(0).edit().putString("voice",i==0?"":voices.get(i-1).getName()).apply();configureVoice();tts.speak("Em trezentos metros, vire à direita.",TextToSpeech.QUEUE_FLUSH,null,"preview");}).setNeutralButton("Vozes do Android",(d,i)->{try{startActivity(new Intent("com.android.settings.TTS_SETTINGS"));}catch(Exception e){toast("Abra as configurações de texto para fala do Android.");}}).setNegativeButton("Fechar",null).show();}
