 static final Map<ArrayList<GeoPoint>,RouteGeometry> geometryCache=Collections.synchronizedMap(new IdentityHashMap<>());
 double[] project(GeoPoint p,ArrayList<GeoPoint> line){
 RouteGeometry g; synchronized(geometryCache){g=geometryCache.get(line);if(g==null){double[] lat=new double[line.size()],lon=new double[line.size()];for(int i=0;i<line.size();i++){lat[i]=line.get(i).getLatitude();lon[i]=line.get(i).getLongitude();}g=new RouteGeometry(lat,lon);if(geometryCache.size()>24)geometryCache.clear();geometryCache.put(line,g);}}
 return g.project(p.getLatitude(),p.getLongitude());
 }
 void progress(){if(loc==null||routes.isEmpty()||destination==null)return;Route r=routes.get(selected);GeoPoint p=gp(loc);double[] pos=project(p,r.points);double remain=Math.max(0,r.meters*(1-pos[0]/Math.max(1,pos[2])));long tick=SystemClock.elapsedRealtime();if(tick-lastEtaRefresh>10000){cachedDelay=estimateJamDelay(r,jams,pos[0]);lastEtaRefresh=tick;}double sec=r.seconds*remain/Math.max(1,r.meters)+cachedDelay;summary.setText(new java.text.SimpleDateFormat("HH:mm",new Locale("pt","BR")).format(new Date(System.currentTimeMillis()+(long)(sec*1000))));arrivalDetail.setText((int)Math.ceil(sec/60)+" min   ·   "+String.format(new Locale("pt","BR"),"%.1f km",remain/1000));if(!stops.isEmpty()&&p.distanceToAsDouble(stops.get(0).p)<35){stops.remove(0);say("Parada alcançada");calculate();return;}if(stops.isEmpty()&&p.distanceToAsDouble(destination.p)<25){driving=false;sheetExpanded=false;previewRoute=false;say("Você chegou ao destino");destination=null;routes.clear();resetCamera();drawRoutes();summary.setText("Destino alcançado");nav.setVisibility(View.GONE);renderRoute();return;}if(loc.hasAccuracy()&&loc.getAccuracy()<35&&pos[1]>Math.max(55,loc.getAccuracy()*2.5)&&loc.hasSpeed()&&loc.getSpeed()>1.2)offRouteSamples++;else offRouteSamples=0;if(offRouteSamples>=3&&!calculating&&SystemClock.elapsedRealtime()-lastRouteAttempt>20000){offRouteSamples=0;say("Recalculando rota");calculate();return;}
 while(stepIndex<r.steps.size()-1&&project(r.steps.get(stepIndex).p,r.points)[0]<pos[0]+8)stepIndex++;if(stepIndex<r.steps.size()){Step s=r.steps.get(stepIndex);double d=Math.max(0,project(s.p,r.points)[0]-pos[0]);nav.setText(d>=1000?String.format(new Locale("pt","BR"),"%.1f km",d/1000):Math.round(d)+" m");navStreet.setText(s.street.isEmpty()?streetFromInstruction(s.text):s.street);if(!s.kind.equals(turnKind)){turnKind=s.kind;turnIcon.setImageDrawable(controlIcon(turnKind,Color.WHITE));}if(d<=55&&warned.add("stepnow"+stepIndex)){warned.add("step"+stepIndex);say(s.text);}else if(d<250&&d>55&&warned.add("step"+stepIndex))say("Em "+Math.round(d/10)*10+" metros, "+s.text);}
 showUpcoming(p,r,pos);warnJam(r,pos,p);if(tick-lastEquipmentUpdate>2500){lastEquipmentUpdate=tick;updateRouteEquipment();maybeLoadCorridor();if(vector!=null&&vector.active())vector.routeProgress();else drawEvents();}if(mode.equals("walk")||pos[1]>65||System.currentTimeMillis()-lastWarn<4500)return;ArrayList<Event> all=roadEvents();Event chosen=null;double nearest=Double.MAX_VALUE;String stage="";for(Event e:all){if(e.expires<System.currentTimeMillis()||e.kind.equals("semaforo"))continue;double max=e.kind.equals("radar")?1000:e.kind.equals("historico")?500:e.kind.equals("lombada")?300:e.kind.equals("video")?500:350;if(p.distanceToAsDouble(e.p)>max+60)continue;double[] v=eventPosition(e,r);double d=v[0]-pos[0];if(v[1]>(e.kind.equals("radar")||e.kind.equals("historico")?55:40)||d<0||d>max||e.kind.equals("lombada")&&!bumpOnRoute(e,r,pos[0]))continue;if(!Double.isNaN(e.direction)&&Math.abs((v[3]-e.direction+540)%360-180)>65)continue;String k=e.id+(e.kind.equals("radar")?(d>500?":1000":d>250?":500":":250"):":near");if(warned.contains(k))continue;if(d<nearest){chosen=e;nearest=d;stage=k;}}if(chosen!=null){warned.add(stage);lastWarn=System.currentTimeMillis();alarm(chosen.kind,(chosen.kind.equals("historico")?"Possível equipamento de fiscalização, situação não confirmada":chosen.label)+" a "+Math.round(nearest/10)*10+" metros"+(chosen.limit>0?". Limite informado: "+(int)chosen.limit+" quilômetros por hora.":"."));}}
 void routePreferences(){String[] names={"Evitar pedágios quando possível","Evitar rodovias quando possível","Evitar ladeiras (modo a pé)","Evitar interdições reportadas"};boolean[] values={avoidTolls,avoidHighways,avoidHills,avoidRisk};new AlertDialog.Builder(this).setTitle("Preferências de rota").setMultiChoiceItems(names,values,(d,i,v)->values[i]=v).setPositiveButton("Aplicar",(d,i)->{avoidTolls=values[0];avoidHighways=values[1];avoidHills=values[2];avoidRisk=values[3];getPreferences(0).edit().putBoolean("tolls",avoidTolls).putBoolean("highways",avoidHighways).putBoolean("hills",avoidHills).putBoolean("risk",avoidRisk).apply();if(destination!=null)calculate();}).setNegativeButton("Cancelar",null).show();}
