 void showUpcoming(GeoPoint p,Route r,double[] pos){Event radar=null,signal=null,roadWarning=null;double rd=1001,sd=501,wd=501;for(Event e:roadEvents()){if(e.p.distanceToAsDouble(p)>1100||e.expires<System.currentTimeMillis())continue;if(!e.kind.equals("radar")&&!e.kind.equals("semaforo")&&!e.kind.equals("video")&&!e.kind.equals("lombada")&&!e.kind.equals("historico"))continue;double[] z=eventPosition(e,r);double d=z[0]-pos[0];if(z[1]>(e.kind.equals("radar")?55:40)||d<(e.kind.equals("semaforo")?-12:0)||e.kind.equals("lombada")&&!bumpOnRoute(e,r,pos[0]))continue;d=Math.max(0,d);if(!Double.isNaN(e.direction)&&Math.abs((z[3]-e.direction+540)%360-180)>65)continue;if(e.kind.equals("radar")&&d<rd){radar=e;rd=d;}if(e.kind.equals("semaforo")&&d<sd){signal=e;sd=d;}if((e.kind.equals("video")&&d<=500||e.kind.equals("lombada")&&d<=300||e.kind.equals("historico")&&d<=500)&&d<wd){roadWarning=e;wd=d;}}Event next=roadWarning!=null&&wd<rd?roadWarning:radar;double nextDist=next==roadWarning?wd:rd;radarBanner.setVisibility(next==null||mode.equals("walk")?View.GONE:View.VISIBLE);if(next!=null){radarBanner.setText((next.kind.equals("historico")?"Possível radar · não confirmado":next.label)+" · "+Math.round(nextDist)+" m"+(next.limit>0&&!next.kind.equals("historico")?" · "+(int)next.limit+" km/h":""));radarBanner.setBackground(bg(next.kind.equals("radar")?dark?0xff4a262a:0xffffe4e4:dark?0xff384439:0xffe7f0e9,14));}observeDelay(p,r,pos,signal,sd);if(signal==null||sd>180||pos[1]>40||mode.equals("walk")){clearSignalWait();return;}String key=delayBucket(signal,eventPosition(signal,r)[3]);if(!signal.id.equals(waitSignalId)){if(waitSignalPoint==null||waitSignalPoint.distanceToAsDouble(signal.p)>25)waitStart=0;waitSignalId=signal.id;waitSignalPoint=signal.p;}if(!key.equals(currentDelayKey)){currentDelayKey=key;currentDelays=readDelays(key);}signalDistance=sd;signalStopCandidate=loc!=null&&loc.hasSpeed()&&loc.getSpeed()<=(waitStart>0?1.3:.8)&&loc.hasAccuracy()&&loc.getAccuracy()<=35&&sd<=85;if(signalStopCandidate){if(waitStart==0)waitStart=SystemClock.elapsedRealtime();}else waitStart=0;renderSignalWait();}
 void clearSignalWait(){waitSignalId=null;waitSignalPoint=null;waitStart=0;signalStopCandidate=false;signalDistance=Double.NaN;currentDelayKey=null;currentDelays.clear();if(!driving)resetObservation();if(signalBanner!=null)signalBanner.setVisibility(View.GONE);}
 void renderSignalWait(){if(signalBanner==null)return;if(!driving||waitSignalId==null||loc==null||SystemClock.elapsedRealtimeNanos()-loc.getElapsedRealtimeNanos()>15000000000L){clearSignalWait();return;}signalBanner.setVisibility(View.VISIBLE);long seconds=waitStart>0?(SystemClock.elapsedRealtime()-waitStart)/1000:0;String text="Semáforo a "+Math.round(signalDistance)+" m";if(SystemClock.elapsedRealtimeNanos()-loc.getElapsedRealtimeNanos()>6000000000L){signalBanner.setText(text+"\nAguardando GPS");return;}if(signalStopCandidate&&seconds>=3)text+=" · Espera: "+String.format(Locale.US,"%02d:%02d",seconds/60,seconds%60);if(signalStopCandidate&&seconds>=3){String estimate=estimateDelay(currentDelays,seconds);if(estimate!=null)text+="\nEspera restante estimada: "+estimate+" · histórico local";}signalBanner.setText(text);}
 String delayBucket(Event signal,double bearing){Calendar c=Calendar.getInstance();int day=c.get(Calendar.DAY_OF_WEEK),hour=c.get(Calendar.HOUR_OF_DAY);int sector=(int)Math.floor((bearing+22.5)/45)%8;return signal.id+"_"+sector+"_"+((day==Calendar.SATURDAY||day==Calendar.SUNDAY)?"fim":"util")+"_"+hour+"_"+mode;}
