 boolean matchesRoute(Event e,Route r,double start){if(e.kind.equals("lombada"))return bumpOnRoute(e,r,start);if(e.expires<System.currentTimeMillis())return false;double[] p=eventPosition(e,r);double tolerance=e.kind.equals("lombada")?25:e.kind.equals("video")?40:48;return p[1]<=tolerance&&p[0]>=start-3&&p[0]<=p[2]+2&&(Double.isNaN(e.direction)||Math.abs((p[3]-e.direction+540)%360-180)<=65);}
 void updateRouteEquipment(){if(routeEquipment==null)return;if(destination==null||routes.isEmpty()){routeEquipment.setVisibility(View.GONE);return;}Route r=routes.get(selected);double start=driving&&loc!=null?project(gp(loc),r.points)[0]:0;int rad=0,bump=0,video=0,signal=0,unverified=0;Map<String,ArrayList<GeoPoint>> seen=new HashMap<>();for(Event e:roadEvents()){if(!e.kind.equals("radar")&&!e.kind.equals("lombada")&&!e.kind.equals("video")&&!e.kind.equals("semaforo")&&!e.kind.equals("historico"))continue;if(!matchesRoute(e,r,start))continue;ArrayList<GeoPoint> a=seen.computeIfAbsent(e.kind,k->new ArrayList<>());boolean duplicate=false;for(GeoPoint p:a)if(p.distanceToAsDouble(e.p)<(e.kind.equals("lombada")?8:20)){duplicate=true;break;}if(duplicate)continue;a.add(e.p);switch(e.kind){case "radar":rad++;break;case "lombada":bump++;break;case "video":video++;break;case "semaforo":signal++;break;case "historico":unverified++;break;}}String status=corridorLoading?" · buscando":corridorRoute!=r||corridorEnd<=0?" · cobertura parcial":corridorEnd<r.meters*.95?" · trecho consultado":" · cadastrados";routeEquipment.setText(rad+" radares · "+bump+" lombadas · "+video+" câmeras"+(driving?"":" · "+signal+" sinais")+"\nNa rota"+status+(unverified>0?" · "+unverified+" não confirmados":""));routeEquipment.setVisibility(!driving||sheetExpanded?View.VISIBLE:View.GONE);}
 void maybeLoadCorridor(){if(routes.isEmpty()||destination==null)return;Route r=routes.get(selected);double from=driving&&loc!=null?project(gp(loc),r.points)[0]:0;long now=SystemClock.elapsedRealtime();if(corridorRoute==r&&(corridorLoading||corridorEnd>Math.min(r.meters,from+12000)-1000||now-corridorLast<60000))return;boolean same=corridorRoute==r;corridorRoute=r;corridorLoading=true;corridorLast=now;if(!same){corridorEvents=new ArrayList<>();corridorEnd=0;}int token=++corridorRequest;ArrayList<GeoPoint> sample=new ArrayList<>();double along=0,last=-99999,end=0;for(int i=0;i<r.points.size();i++){if(i>0)along+=r.points.get(i-1).distanceToAsDouble(r.points.get(i));if(along<from-250)continue;if(along>from+15000)break;if(along-last>=90||sample.isEmpty()||i==r.points.size()-1){sample.add(r.points.get(i));last=along;}end=along;}if(sample.size()<2){corridorLoading=false;corridorEnd=end;return;}final double finish=end;corridorPool.execute(()->{ArrayList<Event> out=new ArrayList<>();boolean ok=false;try{StringBuilder coords=new StringBuilder();for(GeoPoint p:sample){if(coords.length()>0)coords.append(",");coords.append(String.format(Locale.US,"%.5f,%.5f",p.getLatitude(),p.getLongitude()));}String around="(around:100,"+coords+")";String q="[out:json][timeout:22];(node"+around+"[highway=speed_camera];node"+around+"[highway=traffic_signals];node"+around+"[enforcement];relation"+around+"[type=enforcement];node"+around+"[traffic_calming~\"^(bump|hump|table|cushion|rumble_strip|dip|yes)$\"];way"+around+"[traffic_calming~\"^(bump|hump|table|cushion|rumble_strip|dip|yes)$\"];node"+around+"[man_made=surveillance][surveillance=traffic];node"+around+"[man_made=surveillance][\"surveillance:zone\"=traffic];);out geom;";parseOsmRoad(overpass(q),out);ok=true;}catch(Exception ignored){}boolean success=ok;main.post(()->{if(token!=corridorRequest)return;corridorLoading=false;if(success){for(Event e:out)mergeEvent(corridorEvents,e);corridorEnd=finish;}updateRouteEquipment();drawEvents();});});}
 void parseOsmRoad(JSONObject data,ArrayList<Event> out)throws Exception{JSONArray a=data.getJSONArray("elements");for(int i=0;i<a.length();i++){try{JSONObject o=a.getJSONObject(i),t=o.optJSONObject("tags");if(t==null)continue;String enforce=t.optString("enforcement"),high=t.optString("highway");boolean red=enforce.equals("traffic_signals")||enforce.equals("red_light")||enforce.equals("red_light_camera");boolean radar=high.equals("speed_camera")||red||enforce.equals("maxspeed")||enforce.equals("average_speed");boolean bump=t.has("traffic_calming"),signal=high.equals("traffic_signals"),video=t.optString("man_made").equals("surveillance")&&(t.optString("surveillance").equals("traffic")||t.optString("surveillance:zone").equals("traffic"))&&!t.optString("surveillance:type").equalsIgnoreCase("ALPR")&&enforce.isEmpty()&&!radar;if(!radar&&!bump&&!signal&&!video)continue;JSONObject pos=o.has("lat")?o:bump?centerWay(o):devicePoint(o);if(pos==null||!pos.has("lat"))continue;String kind=radar?"radar":bump?"lombada":signal?"semaforo":"video";String label=red?"Radar de avanço de sinal":radar?"Radar cadastrado":bump?"Lombada cadastrada":signal?"Semáforo cadastrado":"Videomonitoramento viário";Event e=new Event("osm"+o.optString("type")+o.optLong("id"),kind,label,"OpenStreetMap",pos.getDouble("lat"),pos.getDouble("lon"));try{String max=t.optString("maxspeed");e.limit=max.endsWith(" mph")?Double.parseDouble(max.replace(" mph",""))*1.609344:Double.parseDouble(max);}catch(Exception ignored){}mergeEvent(out,e);}catch(Exception ignored){}}}
 void loadInfraRadar(GeoPoint p,ArrayList<Event> out)throws Exception{if(!isBrazil(p))return;double radius=.35;String env=(p.getLongitude()-radius)+","+(p.getLatitude()-radius)+","+(p.getLongitude()+radius)+","+(p.getLatitude()+radius);String url="https://geo.infrasa.gov.br/server/rest/services/Hosted/Radar_velocidade_DNIT/FeatureServer/0/query?where=1%3D1&geometry="+enc(env)+"&geometryType=esriGeometryEnvelope&inSR=4326&outSR=4326&outFields=objectid,codigo_equipamento,br,uf,km&returnGeometry=true&f=json";JSONArray a=new JSONObject(get(url)).getJSONArray("features");for(int i=0;i<a.length();i++){try{JSONObject f=a.getJSONObject(i),g=f.getJSONObject("geometry"),at=f.getJSONObject("attributes");GeoPoint pt=new GeoPoint(g.getDouble("y"),g.getDouble("x"));boolean known=false;for(Event e:out)if(e.kind.equals("radar")&&e.p.distanceToAsDouble(pt)<35){known=true;break;}if(!known)mergeEvent(out,new Event("dnit"+at.optString("objectid"),"historico","Radar DNIT cadastrado · operação não confirmada","Infra S.A. / PNCV",pt.getLatitude(),pt.getLongitude()));}catch(Exception ignored){}}}


 String postOverpass(String base,String q)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(base).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(30000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded; charset=UTF-8");c.setRequestProperty("User-Agent","RotaUnica-Android/0.5");byte[] payload=("data="+enc(q)).getBytes(java.nio.charset.StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(payload.length);try{try(OutputStream os=c.getOutputStream()){os.write(payload);}try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>18000000)throw new IOException("Resposta muito grande");}return out.toString("UTF-8");}}finally{c.disconnect();}}
 boolean blockedAhead(Route r,double from){for(Jam j:jams){if(j.expires<System.currentTimeMillis()||j.level!=5)continue;for(GeoPoint p:j.points){double[] x=project(p,r.points);if(x[1]<30&&x[0]>=from&&x[0]<from+10000)return true;}}return false;}
 GeoPoint navigationPoint(){if(loc==null)return new GeoPoint(0,0);GeoPoint p=gp(loc);if(!driving||routes.isEmpty()||!loc.hasAccuracy()||loc.getAccuracy()>35)return p;Route r=routes.get(selected);double[] x=project(p,r.points);if(x[1]>Math.min(20,loc.getAccuracy()+5)||loc.hasBearing()&&loc.hasSpeed()&&loc.getSpeed()>2&&Math.abs((loc.getBearing()-x[3]+540)%360-180)>55)return p;double remain=x[0];for(int i=1;i<r.points.size();i++){GeoPoint a=r.points.get(i-1),b=r.points.get(i);double len=a.distanceToAsDouble(b);if(remain<=len&&len>0)return a.destinationPoint(remain,a.bearingTo(b));remain-=len;}return p;}
 ArrayList<GeoPoint> remainingLine(Route r){if(!driving||loc==null)return r.points;double[] p=project(gp(loc),r.points);if(p[1]>50)return r.points;double remain=p[0];ArrayList<GeoPoint> result=new ArrayList<>();for(int i=1;i<r.points.size();i++){GeoPoint a=r.points.get(i-1),b=r.points.get(i);double len=a.distanceToAsDouble(b);if(remain<=len&&len>0){result.add(a.destinationPoint(Math.max(0,remain),a.bearingTo(b)));for(int k=i;k<r.points.size();k++)result.add(r.points.get(k));return result;}remain-=len;}return r.points;}


 void searchOsmNamedRoads(String q,GeoPoint p,ArrayList<Place> list)throws Exception{String core=AddressRank.core(q);if(core.length()<4)return;String first=core.split(" ")[0];StringBuilder rx=new StringBuilder();for(char c:first.toCharArray()){switch(c){case 'a':rx.append("[aáàãâä]");break;case 'e':rx.append("[eéêèë]");break;case 'i':rx.append("[iíìîï]");break;case 'o':rx.append("[oóòõôö]");break;case 'u':rx.append("[uúùûü]");break;case 'c':rx.append("[cç]");break;default:rx.append(c);}}String query="[out:json][timeout:10];way(around:25000,"+p.getLatitude()+","+p.getLongitude()+")[highway][name~\""+rx+"\",i];out center 70;";JSONArray a=overpass(query).getJSONArray("elements");for(int i=0;i<a.length();i++){JSONObject e=a.getJSONObject(i),t=e.optJSONObject("tags"),g=e.optJSONObject("center");if(t==null||g==null)continue;String n=t.optString("name");if(!AddressRank.prefixMatch(q,n))continue;Place hit=new Place(n,"Via cadastrada · OpenStreetMap",g.getDouble("lat"),g.getDouble("lon"));hit.street=true;list.add(hit);}}

 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
