 @Override protected void onDestroy(){if(vector!=null)vector.destroy();main.removeCallbacksAndMessages(null);if(gps!=null)gps.removeUpdates(this);if(tts!=null)tts.shutdown();if(tone!=null)tone.release();pool.shutdownNow();searchPool.shutdownNow();localAddressPool.shutdownNow();routePool.shutdownNow();trafficPool.shutdownNow();corridorPool.shutdownNow();equipmentPool.shutdownNow();if(map!=null)map.onDetach();super.onDestroy();}
